denied(fn()=>$peer->close($chat,$id,1),'only author closes poll');denied(fn()=>$polls->close($chat,$id,999),'stale close rejected');$polls->close($chat,$id,1);$polls->close($chat,$id,1);ok(!$polls->get($chat,$id)['open']&&$polls->get($chat,$id)['total_votes']===2,'close replay leaves readable final totals');denied(fn()=>$peer->vote($chat,$id,2,2,$key()),'closed poll rejects late vote');
